PRAGMA foreign_keys=ON;
CREATE TABLE ingestion_runs(id TEXT PRIMARY KEY, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, transform_version TEXT NOT NULL);
CREATE TABLE sources(id TEXT PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL, source_url TEXT NOT NULL, citation TEXT NOT NULL, license_note TEXT NOT NULL, retrieved_at TEXT NOT NULL, geography TEXT NOT NULL, limitations TEXT NOT NULL, row_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE source_files(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), filename TEXT NOT NULL, source_url TEXT NOT NULL, sha256 TEXT NOT NULL, bytes INTEGER NOT NULL, retrieved_at TEXT NOT NULL);
CREATE TABLE countries(iso3 TEXT PRIMARY KEY, iso2 TEXT, name TEXT NOT NULL, region TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE bank_districts(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), source_key TEXT NOT NULL, name TEXT, region TEXT, raw_json TEXT NOT NULL);
CREATE TABLE parties(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), source_key TEXT NOT NULL, kind TEXT NOT NULL, display_name TEXT NOT NULL, country TEXT, district_id TEXT REFERENCES bank_districts(id), raw_json TEXT NOT NULL, UNIQUE(source_id,source_key));
CREATE TABLE accounts(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), source_key TEXT NOT NULL, country TEXT, currency TEXT, opened_on TEXT, district_id TEXT REFERENCES bank_districts(id), frequency TEXT, raw_json TEXT NOT NULL);
CREATE TABLE account_parties(account_id TEXT REFERENCES accounts(id), party_id TEXT REFERENCES parties(id), rights TEXT NOT NULL, source_key TEXT NOT NULL, PRIMARY KEY(account_id,party_id));
CREATE TABLE bank_cards(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), card_type TEXT, issued_on TEXT, raw_json TEXT NOT NULL);
CREATE TABLE loan_contracts(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), amount_minor INTEGER, currency TEXT, start_date TEXT, duration_months INTEGER, payment_minor INTEGER, source_status TEXT NOT NULL, raw_json TEXT NOT NULL);
CREATE TABLE payment_orders(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), destination_bank_code TEXT, destination_account TEXT, amount_minor INTEGER, currency TEXT, purpose TEXT, raw_json TEXT NOT NULL);
CREATE TABLE transactions(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), source_key TEXT NOT NULL, account_id TEXT REFERENCES accounts(id), party_id TEXT REFERENCES parties(id), event_type TEXT NOT NULL, amount_value TEXT NOT NULL, amount_minor INTEGER, currency TEXT, occurred_at TEXT, time_precision TEXT NOT NULL, elapsed_seconds REAL, direction TEXT, operation TEXT, balance_minor INTEGER, country_from TEXT, country_to TEXT, source_locator TEXT NOT NULL, raw_json TEXT, UNIQUE(source_id,source_key));
CREATE TABLE transaction_features(transaction_id TEXT PRIMARY KEY REFERENCES transactions(id), feature_json TEXT NOT NULL);
CREATE TABLE transaction_labels(transaction_id TEXT REFERENCES transactions(id), label_type TEXT NOT NULL, label_value INTEGER NOT NULL, source_id TEXT REFERENCES sources(id), PRIMARY KEY(transaction_id,label_type));
CREATE TABLE exchange_rates(rate_date TEXT NOT NULL, base_currency TEXT NOT NULL, quote_currency TEXT NOT NULL, rate TEXT NOT NULL, source_id TEXT REFERENCES sources(id), PRIMARY KEY(rate_date,base_currency,quote_currency));
CREATE TABLE macro_indicators(country_iso3 TEXT REFERENCES countries(iso3), indicator TEXT NOT NULL, year INTEGER NOT NULL, value TEXT, unit TEXT NOT NULL, source_id TEXT REFERENCES sources(id), source_locator TEXT NOT NULL, PRIMARY KEY(country_iso3,indicator,year));
CREATE TABLE risk_entities(id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources(id), original_id TEXT NOT NULL, name TEXT NOT NULL, folded_name TEXT NOT NULL, entity_type TEXT, programs TEXT, remarks TEXT);
CREATE TABLE risk_aliases(id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES risk_entities(id), alias_type TEXT, name TEXT NOT NULL, folded_name TEXT NOT NULL);
CREATE TABLE risk_addresses(id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES risk_entities(id), address TEXT, city TEXT, country TEXT, remarks TEXT);
CREATE TABLE account_daily(account_id TEXT REFERENCES accounts(id), day TEXT NOT NULL, inflow_minor INTEGER NOT NULL, outflow_minor INTEGER NOT NULL, transaction_count INTEGER NOT NULL, min_balance_minor INTEGER, max_balance_minor INTEGER, PRIMARY KEY(account_id,day));
CREATE TABLE quality_checks(id INTEGER PRIMARY KEY, source_id TEXT REFERENCES sources(id), check_name TEXT NOT NULL, affected_rows INTEGER NOT NULL, severity TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE field_lineage(id INTEGER PRIMARY KEY, source_id TEXT REFERENCES sources(id), target_field TEXT NOT NULL, source_field TEXT NOT NULL, transformation TEXT NOT NULL);
CREATE TABLE warehouse_metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX idx_tx_source_date ON transactions(source_id,occurred_at DESC,id);
CREATE INDEX idx_tx_source_id ON transactions(source_id,id);
CREATE INDEX idx_tx_account_date ON transactions(account_id,occurred_at,id);
CREATE INDEX idx_labels_value ON transaction_labels(label_type,label_value,transaction_id);
CREATE INDEX idx_parties_source ON parties(source_id);
CREATE INDEX idx_risk_folded ON risk_entities(folded_name);
CREATE INDEX idx_alias_folded ON risk_aliases(folded_name);
CREATE INDEX idx_macro_year ON macro_indicators(indicator,year,country_iso3);
